use std::collections::HashMap;
use std::sync::{Arc, LazyLock, Mutex};

static CURRENT: LazyLock<Mutex<Arc<HashMap<String, u32>>>> =
    LazyLock::new(|| Mutex::new(Arc::new(HashMap::new())));

fn lookup(k: &str) -> Option<u32> {
    let snap = CURRENT.lock().unwrap().clone();        // one atomic increment
    snap.get(k).copied()                               // read off the snapshot
}
fn add(k: &str, v: u32) {
    let mut guard = CURRENT.lock().unwrap();           // writers serialise
    Arc::make_mut(&mut guard).insert(k.into(), v);     // clones only if shared
}
